async function visitLedger(stream, visitor) {
  const reader = stream.getReader();
  const decoder = new TextDecoder();
  let accepted = 0;
  let rejected = 0;
  let line = 1;
  let buffer = "";
  let stopped = false;
  let cancelled = false;

  async function cancelOnce() {
    if (!cancelled) {
      cancelled = true;
      await reader.cancel();
    }
  }

  async function visitLine(text) {
    if (/^\s*$/.test(text)) return false;

    let value;
    try {
      value = JSON.parse(text);
    } catch {
      rejected++;
      return false;
    }

    accepted++;
    return (await visitor({ line, value })) === false;
  }

  async function consumeCompleteLines() {
    let newline;
    while ((newline = buffer.indexOf("\n")) !== -1) {
      let text = buffer.slice(0, newline);
      buffer = buffer.slice(newline + 1);

      if (text.endsWith("\r")) text = text.slice(0, -1);

      if (await visitLine(text)) return true;
      line++;
    }
    return false;
  }

  try {
    while (true) {
      const { done, value } = await reader.read();

      if (done) break;

      buffer += decoder.decode(value, { stream: true });
      if (await consumeCompleteLines()) {
        stopped = true;
        break;
      }
    }

    if (!stopped) {
      buffer += decoder.decode();

      if (await consumeCompleteLines()) {
        stopped = true;
      } else if (buffer !== "") {
        if (buffer.endsWith("\r")) buffer = buffer.slice(0, -1);
        stopped = await visitLine(buffer);
      }
    }

    if (stopped) await cancelOnce();

    return { accepted, rejected, stopped };
  } catch (error) {
    await cancelOnce();
    throw error;
  } finally {
    reader.releaseLock();
  }
}
